import type { DraftTone, DraftWho } from "./drafts";
import type { Occasion } from "./types";

/*
 * The writing library behind "Help me write it" (the client chose a curated library over AI, 4 Nov).
 * Loaded only when a customer asks for drafts, so it never weighs on the first page load.
 *
 * A letter is built from an opening for the occasion, two paragraphs in the chosen tone, two paragraphs
 * about who it's for, a wish for what comes next, and a closing line. Any mix must fit the scroll's
 * 300 words, so each part has a word budget: opening 40, body 102, two about paragraphs of 52, wish 48, closing 6.
 * Tone bodies are written to suit anyone (romantic is offered for partners only).
 * Puzzle reasons are 5 words at most.
 */

/** Weddings and anniversaries read differently to a partner ("ours") than to anyone else ("yours"). */
export type LetterOccasion =
  | Exclude<Occasion, "anniversary" | "wedding">
  | "anniversary-ours"
  | "anniversary-yours"
  | "wedding-ours"
  | "wedding-yours";

